<?php $title='Rifa '.$raffle['code']; $pct=min(100,((int)$raffle['sold_count']/(int)$raffle['tickets_to_target'])*100); ?><div class="columns"><div class="column is-6"><div class="box product-detail-image"><?php if($raffle['image_path']): ?><img src="<?= e($raffle['image_path']) ?>" alt="<?= e($raffle['product_name']) ?>"><?php else: ?><div class="placeholder-image large">Sin imagen</div><?php endif; ?></div></div><div class="column is-6"><div class="box"><div class="level"><h1 class="title is-3 mb-0"><?= e($raffle['product_name']) ?></h1><span class="tag <?= $raffle['status']==='open'?'is-success':'is-danger' ?>"><?= e($raffle['status']) ?></span></div><p class="mb-5"><?= nl2br(e($raffle['description'])) ?></p><?php if(\App\Core\Auth::check()): ?><div class="info-grid"><div><small>Costo producto</small><strong><?= money($raffle['product_price']) ?></strong></div><?php if(!\App\Core\Auth::isAdmin()): ?><div><small>Boleto 7%</small><strong><?= money($raffle['ticket_price']) ?></strong></div><?php endif; ?><div><small>Boletos para cubrir costo</small><strong><?= (int)$raffle['tickets_to_cover_cost'] ?></strong></div><div><small>Boletos meta 2×</small><strong><?= (int)$raffle['tickets_to_target'] ?></strong></div></div><?php endif; ?><progress class="progress is-primary mt-5" value="<?= (int)$raffle['sold_count'] ?>" max="<?= (int)$raffle['tickets_to_target'] ?>"></progress><p><?= (int)$raffle['sold_count'] ?> de <?= (int)$raffle['tickets_to_target'] ?> boletos vendidos (<?= number_format($pct,1) ?>%).</p><?php if($raffle['status']==='open'): if(\App\Core\Auth::canBuy()): ?><form class="mt-5" method="post" action="<?= route('buy') ?>"><?= csrf_field() ?><input type="hidden" name="raffle_id" value="<?= (int)$raffle['id'] ?>"><label class="label">Cantidad de boletos</label><div class="field has-addons"><p class="control"><input class="input" type="number" name="quantity" min="1" max="<?= max(1,(int)$raffle['tickets_to_target']-(int)$raffle['sold_count']) ?>" value="1" required></p><p class="control is-expanded"><button class="button is-primary is-fullwidth">Comprar boleto</button></p></div><p class="help">Precio por boleto: <?= money($raffle['ticket_price']) ?></p></form><?php elseif(\App\Core\Auth::isAdmin()): ?><div class="notification is-info is-light mt-5">La cuenta de administrador puede consultar la rifa, pero no comprar boletos.</div><?php elseif(\App\Core\Auth::check()): ?><div class="notification is-info is-light mt-5">Tu cuenta está configurada para consultar productos; no puede comprar boletos.</div><?php else: ?><div class="notification is-warning is-light mt-5">Para comprar boletos, <a href="<?= route('login') ?>">inicia sesión</a> o <a href="<?= route('register') ?>">crea una cuenta</a>. Puedes consultar este producto sin registrarte.</div><?php endif; else: ?><div class="notification is-danger is-light mt-5">Esta rifa ya está cerrada.</div><?php endif; ?></div></div></div>
